fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let mut sp: i32 = host::display::state_get(0);
    let mut peak: i32 = host::display::state_get(1);
    if down == 1 {
        sp = sp + 3;
        if sp > 300 { sp = 300; }
    } else {
        sp = sp - 2;
        if sp < 0 { sp = 0; }
    }
    if sp > peak { peak = sp; }
    if t % 20 == 0 && peak > 0 { peak = peak - 1; }
    host::display::state_set(0, sp);
    host::display::state_set(1, peak);
    host::display::clear(0x101010);
    let mut i: i32 = 0;
    while i < 20 {
        let mut c: i32 = 0x202020;
        if sp * 20 / 300 > i {
            c = 0x00cc44;
            if i >= 12 { c = 0xffcc00; }
            if i >= 17 { c = 0xff3030; }
        }
        host::display::fill_rect(30 + i * 13, 140, 10, 40, c);
        i = i + 1;
    }
    let mut pidx: i32 = peak * 20 / 300;
    if pidx > 19 { pidx = 19; }
    host::display::fill_rect(30 + pidx * 13, 128, 10, 6, 0xffffff);
    host::display::draw_string(30, 60, "SPEED", 0x808080, 1);
    host::display::draw_number(30, 76, sp, 0xffffff, 3);
    host::display::draw_string(30, 200, "HOLD TO REV", 0x606060, 1);
    host::display::present();
}
